L693: fn canonicalize_json(value: &Value) -> Value {
L694:     match value {
L695:         Value::Array(items) => Value::Array(items.iter().map(canonicalize_json).collect()),
L696:         Value::Object(map) => {
L697:             let mut entries: Vec<_> = map.iter().collect();
L698:             entries.sort_by_key(|(key, _)| *key);
L699:             let mut sorted = Map::with_capacity(map.len());
L700:             for (key, child) in entries {
L701:                 sorted.insert(key.clone(), canonicalize_json(child));
L702:             }
L703:             Value::Object(sorted)
L704:         }
L705:         _ => value.clone(),
L706:     }
L707: }
